package com.giovannielena.restaurant.service;
import com.giovannielena.restaurant.dto.ReservationDto; import com.giovannielena.restaurant.entity.*; import com.giovannielena.restaurant.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ReservationService { private final ReservationRepository reservations; private final UserRepository users; public ReservationService(ReservationRepository r,UserRepository u){reservations=r;users=u;} public Reservation create(String email,ReservationDto r){User u=users.findByEmail(email).orElseThrow(); Reservation x=new Reservation();x.setUser(u);x.setCustomerName(r.customerName());x.setCustomerEmail(r.customerEmail());x.setCustomerPhone(r.customerPhone());x.setReservationDate(r.reservationDate());x.setReservationTime(r.reservationTime());x.setGuestCount(r.guestCount());x.setSpecialRequest(r.specialRequest());return reservations.save(x);} public List<Reservation> mine(String email){return reservations.findByUserIdOrderByCreatedAtDesc(users.findByEmail(email).orElseThrow().getId());} }